<script setup lang="js">
import {onMounted} from "vue";
import {useRouter} from "vue-router";
import {useI18n} from "vue-i18n";
import useReportingStore from "@/reporting/application/reporting.store.js";
import useIamStore from "@/iam/application/iam.store.js";

/**
 * Registry of the reports generated by the organization, with a shortcut to the session each one documents.
 */
const {t} = useI18n();
const router = useRouter();
const store = useReportingStore();
const iam = useIamStore();

const templateName = (id) => store.getTemplateById(id)?.name ?? `#${id}`;
const userName = (id) => id === iam.userId ? iam.fullName : (iam.users.find(u => u.id === id)?.fullName ?? `#${id}`);
const formatDate = (d) => d ? new Date(d).toLocaleString("es-PE", {dateStyle: "short", timeStyle: "short"}) : "–";
const openSubject = (r) => r.subjectType === "SPRAY_SESSION"
    ? router.push({name: "process-monitoring-session-detail", params: {id: r.subjectId}})
    : router.push({name: "traceability-recuperations"});

onMounted(() => { store.fetchGeneratedReports(); store.fetchTemplates(); if (iam.isAdmin) iam.fetchUsersAndRoles(); });
</script>

<template>
  <section class="p-4 md:p-5">
    <div class="flex align-items-center justify-content-between flex-wrap gap-2 mb-3">
      <div>
        <h1 class="page-title">{{ t('reports.generated-title') }}</h1>
        <p class="m-0 text-color-secondary">{{ t('reports.generated-hint') }}</p>
      </div>
      <pv-button :label="t('reports.manage-templates')" icon="pi pi-objects-column" outlined @click="router.push({name: 'reporting-templates'})"/>
    </div>
    <pv-message v-if="store.error" severity="error" class="mb-3">{{ store.error }}</pv-message>
    <pv-data-table :value="store.generatedReports" :loading="!store.generatedReportsLoaded" paginator :rows="10" striped-rows>
      <template #empty>{{ t('reports.no-generated') }}</template>
      <pv-column :header="t('reports.generated-at')"><template #body="{ data }">{{ formatDate(data.generatedAt) }}</template></pv-column>
      <pv-column field="fileName" :header="t('reports.file')"/>
      <pv-column :header="t('reports.template')"><template #body="{ data }">{{ templateName(data.reportTemplateId) }}</template></pv-column>
      <pv-column :header="t('reports.subject-label')">
        <template #body="{ data }"><pv-button :label="t('reports.subject.' + (data.subjectType === 'SPRAY_SESSION' ? 'session' : 'recuperation')) + ' #' + data.subjectId" link class="p-0" @click="openSubject(data)"/></template>
      </pv-column>
      <pv-column :header="t('reports.generated-by')"><template #body="{ data }">{{ userName(data.generatedByUserId) }}</template></pv-column>
      <pv-column field="format" :header="t('reports.format')" style="width: 6rem"/>
    </pv-data-table>
  </section>
</template>

